//! Uncertainty propagation and adaptive window transaction for collective packet trajectories.
//!
//! Research node LP04 of `research/promotion_loop12_20261011/PORTING_DAG.json`.
//! Implements multi-window causal packet advancement with:
//! 1. Inherited uncertainty transfer across windows:
//!    \[
//!    \rho_{\text{mean}}^{(k)} = \sum_j w_j \rho_j^{(k)}, \quad E_{\text{mean}}^{(k+1)} = \frac{D + \tau(A_0 + h G / (p+2)) + \rho_{\text{mean}}^{(k)}}{1 - h L}
//!    \]
//!    \[
//!    E_{\text{mode}, j}^{(k+1)} = B(|z_j| + h G / (p+2)) + h L_F E_{\text{mean}}^{(k+1)} + \rho_j^{(k)}
//!    \]
//! 2. Strict transactional atomicity: rejected trials reduce step size but cannot mutate accepted
//!    time, state, or error bounds; all work counters accumulate monotonically across attempts.
//! 3. Output policy separating mean-only and full-mode trajectory records.
//!
//! Radii are analytic estimates evaluated in ordinary binary64. The returned
//! `roundoff_enclosed = false` keeps production certification explicitly open.

use serde::{Deserialize, Serialize};

use crate::collective_model::CollectiveModel;
use crate::packet_window::{
    CausalWeights, OutwardPacketRequest, PacketError, compile_packet, compute_certificate,
    generate_candidate, reconstruct_modes, reconstruct_outward_at_times,
};
use crate::packet_work::PacketWorkCounters;
use rodas5p_core::directed::{Interval, add_up, mul_up, sqrt_up};
use rodas5p_core::{CoreError, CoreResult};
use thiserror::Error;

/// Output reporting policy.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum OutputPolicy {
    /// Records time, mean, and diagnostic mean radius.
    MeanOnly,
    /// Records time, mean, mean radius, plus all microscopic modes and mode radii.
    AllModes,
}

/// A recorded step in the packet trajectory.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TrajectoryStep {
    pub t: f64,
    pub h: f64,
    pub mean: (f64, f64),
    pub mean_radius: f64,
    pub modes: Option<Vec<(f64, f64)>>,
    pub mode_radii: Option<Vec<f64>>,
    pub local_defect: f64,
    pub total_mean_bound: f64,
}

/// Configuration for adaptive multi-window packet integration.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TrajectoryConfig {
    pub t_start: f64,
    pub t_end: f64,
    pub initial_h: f64,
    pub min_h: f64,
    pub max_h: f64,
    pub order: usize,
    pub degree: usize,
    pub sweeps: usize,
    pub mean_tolerance: f64,
    pub mode_tolerance: f64,
    pub output_policy: OutputPolicy,
    pub max_steps: usize,
}

impl TrajectoryConfig {
    pub fn new(
        t_start: f64,
        t_end: f64,
        initial_h: f64,
        mean_tolerance: f64,
        mode_tolerance: f64,
    ) -> CoreResult<Self> {
        if !t_start.is_finite() || !t_end.is_finite() || t_end <= t_start {
            return Err(CoreError::InvalidInput(format!(
                "packet_trajectory: t_end ({t_end}) must be strictly greater than t_start ({t_start})"
            )));
        }
        if !initial_h.is_finite() || initial_h <= 0.0 {
            return Err(CoreError::InvalidInput(format!(
                "packet_trajectory: initial_h must be positive finite, got {initial_h}"
            )));
        }
        if !mean_tolerance.is_finite() || mean_tolerance <= 0.0 {
            return Err(CoreError::InvalidInput(format!(
                "packet_trajectory: mean_tolerance must be positive finite, got {mean_tolerance}"
            )));
        }
        if !mode_tolerance.is_finite() || mode_tolerance <= 0.0 {
            return Err(CoreError::InvalidInput(format!(
                "packet_trajectory: mode_tolerance must be positive finite, got {mode_tolerance}"
            )));
        }

        Ok(Self {
            t_start,
            t_end,
            initial_h,
            min_h: 1e-6,
            max_h: initial_h * 2.0,
            order: 8,
            degree: 10,
            sweeps: 4,
            mean_tolerance,
            mode_tolerance,
            output_policy: OutputPolicy::MeanOnly,
            max_steps: 1000,
        })
    }
}

/// Outcome of a full trajectory integration.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct PacketTrajectoryResult {
    /// False: the current packet arithmetic does not enclose floating-point error.
    pub roundoff_enclosed: bool,
    pub final_t: f64,
    pub final_mean: (f64, f64),
    pub final_mean_radius: f64,
    pub final_modes: Vec<(f64, f64)>,
    pub final_mode_radii: Vec<f64>,
    pub steps: Vec<TrajectoryStep>,
    pub accepted_steps: usize,
    pub rejected_steps: usize,
    pub work: PacketWorkCounters,
}

/// A provisional point on the linear outward trajectory. Its radii are
/// computed around the returned centers and transport initial uncertainty,
/// but have no certified authority while `roundoff_enclosed` is false.
#[derive(Clone, Debug, PartialEq)]
pub struct LinearOutwardPoint {
    pub t: f64,
    pub mean: (f64, f64),
    pub mean_radius: f64,
    pub modes: Option<Vec<(f64, f64)>>,
    pub mode_radii: Option<Vec<f64>>,
}

/// Scoped result for the linear member of the packet family. Authority stays
/// false until the local outward primitive and its composition are reviewed.
#[derive(Clone, Debug, PartialEq)]
pub struct LinearOutwardTrajectory {
    pub roundoff_enclosed: bool,
    pub observations: Vec<LinearOutwardPoint>,
    pub endpoints: Vec<LinearOutwardPoint>,
    pub accepted_steps: usize,
    pub rejected_steps: usize,
    pub work: PacketWorkCounters,
}

/// Typed refusal for unsupported models, time grids, and adaptive exhaustion.
#[derive(Clone, Debug, PartialEq, Error)]
pub enum LinearTrajectoryRefusal {
    #[error("linear outward trajectory requires chi = kappa = 0")]
    UnsupportedModel,
    #[error("invalid linear outward trajectory request: {0}")]
    InvalidInput(&'static str),
    #[error("requested times do not admit exact binary64 local offsets")]
    NonExactTimeGrid,
    #[error("linear outward packet refused: {0}")]
    Packet(#[from] PacketError),
    #[error("adaptive linear outward trajectory exhausted its step limit")]
    StepLimit,
    #[error("adaptive linear outward trajectory reached its minimum step")]
    MinimumStep,
}

fn exact_offset(t: f64, origin: f64) -> Result<f64, LinearTrajectoryRefusal> {
    let offset = t - origin;
    let exact = Interval::point(t)
        .and_then(|a| a.sub(Interval::point(origin)?))
        .map_err(|_| LinearTrajectoryRefusal::NonExactTimeGrid)?;
    if !offset.is_finite() || exact.lo != offset || exact.hi != offset {
        return Err(LinearTrajectoryRefusal::NonExactTimeGrid);
    }
    Ok(offset)
}

fn outward_point(
    output: &crate::packet_window::OutwardPacketOutput,
    index: usize,
    t: f64,
    n: usize,
    policy: OutputPolicy,
) -> Result<LinearOutwardPoint, LinearTrajectoryRefusal> {
    let start = index
        .checked_mul(n)
        .ok_or(LinearTrajectoryRefusal::InvalidInput(
            "output index overflow",
        ))?;
    let end = start
        .checked_add(n)
        .ok_or(LinearTrajectoryRefusal::InvalidInput(
            "output index overflow",
        ))?;
    let modes = output
        .modes
        .get(start..end)
        .ok_or(LinearTrajectoryRefusal::InvalidInput(
            "outward output shape",
        ))?;
    let radii = output
        .mode_radii
        .get(start..end)
        .ok_or(LinearTrajectoryRefusal::InvalidInput(
            "outward radius shape",
        ))?;
    let mean = *output
        .means
        .get(index)
        .ok_or(LinearTrajectoryRefusal::InvalidInput("outward mean shape"))?;
    let mean_radius =
        *output
            .mean_radii
            .get(index)
            .ok_or(LinearTrajectoryRefusal::InvalidInput(
                "outward mean radius shape",
            ))?;
    Ok(LinearOutwardPoint {
        t,
        mean,
        mean_radius,
        modes: (policy == OutputPolicy::AllModes).then(|| modes.to_vec()),
        mode_radii: (policy == OutputPolicy::AllModes).then(|| radii.to_vec()),
    })
}

/// Composes A01's local pointwise outward enclosures for the exactly linear
/// family. The exact time-offset gate avoids silently relabeling a local
/// enclosure at a rounded time as one at the requested global time. A rejected
/// trial commits no state or output; its packet work remains in `work`.
pub fn run_linear_outward_trajectory(
    model: &CollectiveModel,
    initial_radii: Option<&[f64]>,
    config: &TrajectoryConfig,
    requested_times: &[f64],
    work: &mut PacketWorkCounters,
) -> Result<LinearOutwardTrajectory, LinearTrajectoryRefusal> {
    if model.chi() != 0.0 || model.kappa() != 0.0 {
        return Err(LinearTrajectoryRefusal::UnsupportedModel);
    }
    TrajectoryConfig::new(
        config.t_start,
        config.t_end,
        config.initial_h,
        config.mean_tolerance,
        config.mode_tolerance,
    )
    .map_err(|_| LinearTrajectoryRefusal::InvalidInput("nonfinite time, step or tolerance"))?;
    if !config.min_h.is_finite()
        || config.min_h <= 0.0
        || !config.max_h.is_finite()
        || config.max_h < config.min_h
        || config.degree < config.order
        || config.sweeps == 0
        || config.max_steps == 0
        || config.degree.checked_mul(3).is_none()
        || config.order.checked_add(1).is_none()
        || config.degree.checked_add(1).is_none()
        || config
            .degree
            .checked_mul(3)
            .and_then(|n| n.checked_add(1))
            .is_none()
    {
        return Err(LinearTrajectoryRefusal::InvalidInput(
            "invalid packet configuration",
        ));
    }
    if requested_times
        .iter()
        .any(|t| !t.is_finite() || *t < config.t_start || *t > config.t_end)
        || requested_times.windows(2).any(|pair| pair[0] >= pair[1])
    {
        return Err(LinearTrajectoryRefusal::InvalidInput(
            "requested times must be finite, ordered and in range",
        ));
    }
    let n = model.num_modes();
    let mut radii = match initial_radii {
        Some(input) if input.len() == n && input.iter().all(|r| r.is_finite() && *r >= 0.0) => {
            input.to_vec()
        }
        Some(_) => {
            return Err(LinearTrajectoryRefusal::InvalidInput(
                "invalid initial radii",
            ));
        }
        None => vec![0.0; n],
    };
    let table = CausalWeights::compile(config.order, 3 * config.degree);
    let mut current = model.clone();
    let mut t = config.t_start;
    let mut h = config.initial_h.min(config.max_h);
    let mut observations = Vec::with_capacity(requested_times.len() + 2);
    let mut endpoints = Vec::new();
    let mut next_request = 0;
    let mut accepted_steps = 0;
    let mut rejected_steps = 0;
    let mut last_packet_error = None;
    while t < config.t_end {
        if accepted_steps + rejected_steps >= config.max_steps {
            return Err(LinearTrajectoryRefusal::StepLimit);
        }
        let remaining = exact_offset(config.t_end, t)?;
        let step_h = h.min(remaining);
        if step_h < config.min_h || t + step_h <= t {
            return Err(last_packet_error
                .map(LinearTrajectoryRefusal::Packet)
                .unwrap_or(LinearTrajectoryRefusal::MinimumStep));
        }
        let next_t = t + step_h;
        let exact_next = Interval::exact_sum(t, step_h)
            .map_err(|_| LinearTrajectoryRefusal::NonExactTimeGrid)?;
        if exact_next.lo != next_t || exact_next.hi != next_t {
            return Err(LinearTrajectoryRefusal::NonExactTimeGrid);
        }
        let mut local_times = Vec::new();
        let first = endpoints.is_empty();
        if first {
            local_times.push(0.0);
        }
        let mut count_request = 0;
        while next_request + count_request < requested_times.len()
            && requested_times[next_request + count_request] < next_t
        {
            let requested = requested_times[next_request + count_request];
            if requested > t {
                local_times.push(exact_offset(requested, t)?);
            }
            count_request += 1;
        }
        local_times.push(step_h);
        let attempt = (|| -> Result<_, PacketError> {
            let packet = compile_packet(&current, step_h, config.order, work)?;
            let candidate =
                generate_candidate(&packet, config.degree, config.sweeps, &table, work)?;
            reconstruct_outward_at_times(
                &candidate,
                &packet,
                OutwardPacketRequest {
                    times: &local_times,
                    initial_radii: &radii,
                },
                work,
            )
        })();
        let output = match attempt {
            Ok(output) => output,
            Err(error) => {
                last_packet_error = Some(error);
                rejected_steps += 1;
                h = step_h * 0.5;
                continue;
            }
        };
        last_packet_error = None;
        let last = local_times.len() - 1;
        let start = last * n;
        let endpoint_radii = output.mode_radii.get(start..start + n).ok_or(
            LinearTrajectoryRefusal::InvalidInput("outward endpoint shape"),
        )?;
        let endpoint_mean_radius =
            output
                .mean_radii
                .get(last)
                .ok_or(LinearTrajectoryRefusal::InvalidInput(
                    "outward endpoint mean shape",
                ))?;
        if *endpoint_mean_radius > config.mean_tolerance
            || endpoint_radii.iter().any(|r| *r > config.mode_tolerance)
        {
            rejected_steps += 1;
            h = step_h * 0.5;
            continue;
        }
        let endpoint_modes =
            output
                .modes
                .get(start..start + n)
                .ok_or(LinearTrajectoryRefusal::InvalidInput(
                    "outward endpoint shape",
                ))?;
        let next_model = match CollectiveModel::new(
            current.xi().to_vec(),
            current.weights().to_vec(),
            endpoint_modes.to_vec(),
            current.width(),
            current.chi(),
            current.carrier(),
            current.kappa(),
        ) {
            Ok(next) => next,
            Err(_) => {
                rejected_steps += 1;
                h = step_h * 0.5;
                continue;
            }
        };
        let mut index = 0;
        if first {
            let initial = outward_point(&output, 0, t, n, config.output_policy)?;
            observations.push(initial.clone());
            endpoints.push(initial);
            index += 1;
        }
        for requested in &requested_times[next_request..next_request + count_request] {
            if *requested > t {
                observations.push(outward_point(
                    &output,
                    index,
                    *requested,
                    n,
                    config.output_policy,
                )?);
                index += 1;
            }
        }
        let endpoint = outward_point(&output, last, next_t, n, config.output_policy)?;
        if requested_times.get(next_request + count_request) == Some(&next_t) {
            observations.push(endpoint.clone());
            count_request += 1;
        }
        endpoints.push(endpoint.clone());
        if next_t == config.t_end && observations.last().map(|p| p.t) != Some(next_t) {
            observations.push(endpoint);
        }
        next_request += count_request;
        t = next_t;
        current = next_model;
        radii.copy_from_slice(endpoint_radii);
        accepted_steps += 1;
        h = step_h;
    }
    Ok(LinearOutwardTrajectory {
        roundoff_enclosed: false,
        observations,
        endpoints,
        accepted_steps,
        rejected_steps,
        work: *work,
    })
}

fn complex_mean(weights: &[f64], z: &[(f64, f64)]) -> (f64, f64) {
    let mut re = 0.0;
    let mut im = 0.0;
    for (&w, &(u, v)) in weights.iter().zip(z.iter()) {
        re += w * u;
        im += w * v;
    }
    (re, im)
}

/// Executes a transactional, adaptive multi-window packet trajectory.
pub fn run_packet_trajectory(
    model: &CollectiveModel,
    initial_radii: Option<&[f64]>,
    config: &TrajectoryConfig,
    work: &mut PacketWorkCounters,
) -> CoreResult<PacketTrajectoryResult> {
    // Config is public and deserializable, so constructor checks alone do not
    // establish the contract at this execution boundary.
    TrajectoryConfig::new(
        config.t_start,
        config.t_end,
        config.initial_h,
        config.mean_tolerance,
        config.mode_tolerance,
    )?;
    if !config.min_h.is_finite()
        || config.min_h <= 0.0
        || !config.max_h.is_finite()
        || config.max_h < config.min_h
        || config.degree < config.order
        || config.sweeps == 0
        || config.max_steps == 0
        || config.degree.checked_mul(3).is_none()
    {
        return Err(CoreError::InvalidInput(
            "packet_trajectory: invalid step bounds, degree, sweeps or step limit".into(),
        ));
    }
    if model.kappa() != 0.0 {
        return Err(CoreError::InvalidInput(
            "packet_trajectory: kappa > 0 requires an implemented damped packet route".into(),
        ));
    }
    let num_modes = model.num_modes();

    // Validate initial radii if provided
    let mut current_radii = if let Some(radii) = initial_radii {
        if radii.len() != num_modes {
            return Err(CoreError::InvalidInput(format!(
                "packet_trajectory: initial_radii length {} != model modes {num_modes}",
                radii.len()
            )));
        }
        for (idx, &r) in radii.iter().enumerate() {
            if !r.is_finite() || r < 0.0 {
                return Err(CoreError::InvalidInput(format!(
                    "packet_trajectory: initial_radii[{idx}] must be non-negative finite, got {r}"
                )));
            }
        }
        radii.to_vec()
    } else {
        vec![0.0; num_modes]
    };

    // Energy conservation and |mean|^2 <= (sum weights) * energy prove the
    // true mean stays in the unit disk for every permitted initial state.
    // Enclose the energy of the product of complex uncertainty disks outward.
    let mut initial_energy_upper = 0.0;
    let mut weight_sum_upper = 0.0;
    for ((&w, &(re, im)), &radius) in model
        .weights()
        .iter()
        .zip(model.initial_amplitudes())
        .zip(&current_radii)
    {
        weight_sum_upper = add_up(weight_sum_upper, w)?;
        let magnitude = sqrt_up(add_up(mul_up(re, re)?, mul_up(im, im)?)?)?;
        let outer_radius = add_up(magnitude, radius)?;
        initial_energy_upper = add_up(
            initial_energy_upper,
            mul_up(w, mul_up(outer_radius, outer_radius)?)?,
        )?;
    }
    let initial_mean_squared_upper = mul_up(weight_sum_upper, initial_energy_upper)?;
    if initial_mean_squared_upper > 1.0 {
        return Err(CoreError::InvalidInput(format!(
            "packet_trajectory: initial uncertainty mean-squared upper bound {initial_mean_squared_upper} exceeds proved unit domain"
        )));
    }

    let weights_table = CausalWeights::compile(config.order, 3 * config.degree);

    let mut t = config.t_start;
    let mut current_model = model.clone();
    let mut h = config.initial_h.min(config.max_h).min(config.t_end - t);

    let mut steps = Vec::new();
    let mut accepted_steps = 0;
    let mut rejected_steps = 0;

    // Record initial step t_start
    let initial_mean = complex_mean(current_model.weights(), current_model.initial_amplitudes());
    let mut initial_mean_radius = 0.0;
    for (&w, &r) in current_model.weights().iter().zip(current_radii.iter()) {
        initial_mean_radius += w * r;
    }

    steps.push(TrajectoryStep {
        t,
        h: 0.0,
        mean: initial_mean,
        mean_radius: initial_mean_radius,
        modes: if config.output_policy == OutputPolicy::AllModes {
            Some(current_model.initial_amplitudes().to_vec())
        } else {
            None
        },
        mode_radii: if config.output_policy == OutputPolicy::AllModes {
            Some(current_radii.clone())
        } else {
            None
        },
        local_defect: 0.0,
        total_mean_bound: initial_mean_radius,
    });

    while t < config.t_end {
        if accepted_steps + rejected_steps >= config.max_steps {
            return Err(CoreError::NonlinearSolve(format!(
                "packet_trajectory: exceeded max_steps limit {}",
                config.max_steps
            )));
        }

        // Clamp step to not overshoot t_end
        let step_h = h.min(config.t_end - t);
        if t + step_h <= t || !(t + step_h).is_finite() {
            return Err(CoreError::InvalidInput(
                "packet_trajectory: step cannot advance representable time".into(),
            ));
        }
        if step_h < config.min_h {
            return Err(CoreError::NonlinearSolve(format!(
                "packet_trajectory: step size {step_h:e} fell below min_h {:e} at t={t}",
                config.min_h
            )));
        }

        // --- Transactional Attempt ---
        // Compute inherited mean radius
        let mut inherited_mean_radius = 0.0;
        for (&w, &r) in current_model.weights().iter().zip(current_radii.iter()) {
            inherited_mean_radius += w * r;
        }

        let packet_res = compile_packet(&current_model, step_h, config.order, work);
        let packet = match packet_res {
            Ok(p) => p,
            Err(_) => {
                // Rejection: shrink step and retry
                rejected_steps += 1;
                h = (step_h * 0.5).max(config.min_h * 0.5);
                continue;
            }
        };

        let cand_res =
            generate_candidate(&packet, config.degree, config.sweeps, &weights_table, work);
        let cand = match cand_res {
            Ok(c) => c,
            Err(_) => {
                rejected_steps += 1;
                h = (step_h * 0.5).max(config.min_h * 0.5);
                continue;
            }
        };

        let cert_res = compute_certificate(&cand, &packet, &weights_table, work);
        let cert = match cert_res {
            Ok(c) => c,
            Err(_) => {
                rejected_steps += 1;
                h = (step_h * 0.5).max(config.min_h * 0.5);
                continue;
            }
        };

        // Transfer theorem: total mean bound incorporating inherited uncertainty
        let denom = 1.0 - step_h * cert.lipschitz_l;
        if denom <= 0.0 {
            rejected_steps += 1;
            h = (step_h * 0.5).max(config.min_h * 0.5);
            continue;
        }

        // kernel_model already equals tau * (A0 + h*G/(p+2)).
        // Add it once; it is not the force magnitude G.
        let num = cert.volterra_defect + cert.kernel_model + inherited_mean_radius;
        let total_mean_bound = num / denom;

        // Transfer theorem: mode bounds
        let mut new_mode_radii = Vec::with_capacity(num_modes);
        let mut max_mode_bound: f64 = 0.0;

        for (&local_bound, &prev_r) in cert.mode_bounds.iter().zip(&current_radii) {
            let mode_b = local_bound
                + step_h * cert.microscopic_lipschitz_l * inherited_mean_radius / denom
                + prev_r;
            max_mode_bound = max_mode_bound.max(mode_b);
            new_mode_radii.push(mode_b);
        }

        // Budget check
        let accepted =
            total_mean_bound <= config.mean_tolerance && max_mode_bound <= config.mode_tolerance;

        if accepted {
            // Reconstruct new microscopic mode amplitudes
            let new_modes = match reconstruct_modes(&cand, &packet, work) {
                Ok(modes) => modes,
                Err(_) => {
                    rejected_steps += 1;
                    h = (step_h * 0.5).max(config.min_h * 0.5);
                    continue;
                }
            };

            // Construct new admitted model for the subsequent window
            let next_model_res = CollectiveModel::new(
                current_model.xi().to_vec(),
                current_model.weights().to_vec(),
                new_modes.clone(),
                current_model.width(),
                current_model.chi(),
                current_model.carrier(),
                current_model.kappa(),
            );

            let next_model = match next_model_res {
                Ok(m) => m,
                Err(_) => {
                    // Refusal to admit: treat as rejected step
                    rejected_steps += 1;
                    h = (step_h * 0.5).max(config.min_h * 0.5);
                    continue;
                }
            };

            // Commit transaction
            t += step_h;
            current_model = next_model;
            current_radii = new_mode_radii.clone();
            accepted_steps += 1;

            let step_mean =
                complex_mean(current_model.weights(), current_model.initial_amplitudes());
            steps.push(TrajectoryStep {
                t,
                h: step_h,
                mean: step_mean,
                mean_radius: total_mean_bound,
                modes: if config.output_policy == OutputPolicy::AllModes {
                    Some(new_modes)
                } else {
                    None
                },
                mode_radii: if config.output_policy == OutputPolicy::AllModes {
                    Some(new_mode_radii)
                } else {
                    None
                },
                local_defect: cert.volterra_defect,
                total_mean_bound,
            });

            // Conservative step adjustment
            h = (step_h * 1.25).min(config.max_h);
        } else {
            // Rejected transaction: accepted state remains completely pristine
            rejected_steps += 1;
            h = (step_h * 0.5).max(config.min_h * 0.5);
        }
    }

    let final_mean = complex_mean(current_model.weights(), current_model.initial_amplitudes());
    let mut final_mean_radius = 0.0;
    for (&w, &r) in current_model.weights().iter().zip(current_radii.iter()) {
        final_mean_radius += w * r;
    }

    Ok(PacketTrajectoryResult {
        roundoff_enclosed: false,
        final_t: t,
        final_mean,
        final_mean_radius,
        final_modes: current_model.initial_amplitudes().to_vec(),
        final_mode_radii: current_radii,
        steps,
        accepted_steps,
        rejected_steps,
        work: *work,
    })
}

//! Immutable represented packet curves and continuous interval residuals.
//!
//! The rounded binary64 mode coefficients define the represented curve. The
//! exact weighted mean and continuous ODE residual of that frozen curve are
//! then enclosed with outward intervals. This local object does not change
//! packet certificate authority or certify trajectories across windows.

use rodas5p_core::directed::{Interval, add_up, mul_up, sqrt_up};

use super::CollectiveModel;
use super::{
    CompiledPacket, IComplex, PacketCandidate, PacketError, PacketIdentity, PacketWorkCounters,
    c_add, c_mul, c_scale, checked_capacity,
};

#[path = "packet_curve_output.rs"]
mod output;
pub use output::{
    PacketCertifiedView, PacketCurveOutput, PacketCurveOutputView, PacketCurveOutputWorkspace,
    PacketFrozenOutput,
};

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PacketComplexInterval {
    pub re: Interval,
    pub im: Interval,
}

impl From<IComplex> for PacketComplexInterval {
    fn from(value: IComplex) -> Self {
        Self {
            re: value.re,
            im: value.im,
        }
    }
}

impl From<PacketComplexInterval> for IComplex {
    fn from(value: PacketComplexInterval) -> Self {
        Self {
            re: value.re,
            im: value.im,
        }
    }
}

/// A frozen binary64 polynomial per microscopic mode, with outward interval
/// coefficients for its exact weighted mean and exact continuous-model
/// residual. Coefficients are in normalized time `tau=t/h`, and the residual
/// derivative is in physical time.
///
/// The maximum mode degree is `D=p+3d+1`, where p is the linear kernel order
/// and d is the candidate mean degree. Each mode stores D+1 coefficients;
/// each residual stores 3D+1 coefficients. The arrays are private and the
/// type is immutable after construction.
#[derive(Clone, Debug)]
pub struct RepresentedPacketCurve {
    source_identity: PacketIdentity,
    source_candidate_bits: Vec<(u64, u64)>,
    source_candidate_degree: usize,
    source_candidate_sweeps: usize,
    horizon: f64,
    maximum_degree: usize,
    residual_stride: usize,
    mode_coefficients: Vec<(f64, f64)>,
    mean_coefficients: Vec<PacketComplexInterval>,
    residual_coefficients: Vec<PacketComplexInterval>,
    residual_bound: ContinuousPacketResidualBound,
}

/// Coefficient-sum bounds for the represented continuous curve.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ContinuousPacketResidualBound {
    /// Upper bound on `sup_tau ||R(Y(tau))||_w`.
    pub weighted_residual_sup: Interval,
    /// Upper bound on `sup_tau |M_Y(tau)|`.
    pub mean_magnitude_sup: Interval,
}

impl RepresentedPacketCurve {
    /// Freeze the rounded mode reconstruction and enclose all coefficients of
    /// its exact continuous-model residual.
    pub fn freeze(
        candidate: &PacketCandidate,
        packet: &CompiledPacket,
        work: &mut PacketWorkCounters,
    ) -> Result<Self, PacketError> {
        packet.validate_identity(work)?;
        work.identity_comparison_items += packet.identity.scalar_items();
        if !candidate.identity.matches_identity(&packet.identity) {
            return Err(PacketError::CandidatePacketMismatch);
        }
        if packet.model.kappa() != 0.0 {
            return Err(PacketError::UnsupportedDamping(packet.model.kappa()));
        }
        let candidate_len = candidate
            .degree
            .checked_add(1)
            .ok_or(PacketError::SizeOverflow("represented candidate degree"))?;
        if candidate.mean.len() != candidate_len {
            return Err(PacketError::OutwardRefusal(
                "represented candidate shape mismatch",
            ));
        }
        if candidate.degree < packet.order {
            return Err(PacketError::DegreeLessThanOrder {
                degree: candidate.degree,
                order: packet.order,
            });
        }
        if candidate
            .mean
            .iter()
            .any(|&(re, im)| !re.is_finite() || !im.is_finite())
        {
            return Err(PacketError::NonFinite("represented candidate coefficient"));
        }
        if packet.order > (1_u64 << 53) as usize || candidate.degree > (1_u64 << 53) as usize {
            return Err(PacketError::OutwardRefusal(
                "represented polynomial integer exceeds exact binary64 range",
            ));
        }

        let maximum_degree = checked_maximum_degree(packet.order, candidate.degree)?;
        let forcing_len = candidate
            .degree
            .checked_mul(3)
            .and_then(|x| x.checked_add(1))
            .ok_or(PacketError::SizeOverflow(
                "represented forcing coefficients",
            ))?;
        let mode_stride = maximum_degree
            .checked_add(1)
            .ok_or(PacketError::SizeOverflow("represented mode stride"))?;
        let residual_stride = maximum_degree
            .checked_mul(3)
            .and_then(|x| x.checked_add(1))
            .ok_or(PacketError::SizeOverflow("represented residual stride"))?;
        let n = packet.model.num_modes();
        let mode_items = n
            .checked_mul(mode_stride)
            .ok_or(PacketError::SizeOverflow("represented mode coefficients"))?;
        let residual_items = n
            .checked_mul(residual_stride)
            .ok_or(PacketError::SizeOverflow(
                "represented residual coefficients",
            ))?;
        let beta_cols = forcing_len;
        let beta_rows = packet
            .order
            .checked_add(1)
            .ok_or(PacketError::SizeOverflow("represented beta rows"))?;
        let beta_items = beta_rows
            .checked_mul(beta_cols)
            .ok_or(PacketError::SizeOverflow("represented beta table"))?;

        let forcing = rounded_candidate_force(&candidate.mean, packet.model.chi(), work)?;
        if forcing.len() != forcing_len {
            return Err(PacketError::OutwardRefusal(
                "represented forcing shape mismatch",
            ));
        }

        // Beta(l,k)=B(l+1,k+1), generated once by a row recurrence.
        let mut beta = counted_capacity::<f64>(beta_items, "represented beta table", work)?;
        beta.resize(beta_items, 0.0);
        for l in 0..=packet.order {
            work.reconstruction_terms += 1;
            beta[l * beta_cols] = 1.0 / ((l + 1) as f64);
            if !beta[l * beta_cols].is_finite() {
                return Err(PacketError::OutwardRefusal("represented beta overflow"));
            }
            for k in 1..forcing_len {
                work.reconstruction_terms += 2;
                let denominator = l
                    .checked_add(k)
                    .and_then(|x| x.checked_add(1))
                    .ok_or(PacketError::SizeOverflow("represented beta denominator"))?;
                let ratio = (k as f64) / (denominator as f64);
                beta[l * beta_cols + k] = beta[l * beta_cols + k - 1] * ratio;
                if !ratio.is_finite() || !beta[l * beta_cols + k].is_finite() {
                    return Err(PacketError::OutwardRefusal("represented beta overflow"));
                }
            }
        }

        let mut mode_coefficients =
            counted_capacity::<(f64, f64)>(mode_items, "represented mode coefficients", work)?;
        mode_coefficients.resize(mode_items, (0.0, 0.0));
        let basis_len = packet
            .order
            .checked_add(1)
            .ok_or(PacketError::SizeOverflow("represented basis"))?;
        let mut basis = counted_capacity::<(f64, f64)>(basis_len, "represented basis", work)?;
        basis.resize(basis_len, (0.0, 0.0));
        let mut convolution =
            counted_capacity::<(f64, f64)>(mode_stride, "represented convolution", work)?;
        convolution.resize(mode_stride, (0.0, 0.0));

        for j in 0..n {
            convolution.fill((0.0, 0.0));
            let xi = packet.model.xi()[j];
            // This defines rounded curve coefficients only; the residual
            // below uses the exact outward product width*xi.
            work.reconstruction_terms += 2;
            let omega_h = packet.model.width() * xi * packet.horizon;
            if !omega_h.is_finite() {
                return Err(PacketError::OutwardRefusal(
                    "represented width-frequency-horizon overflow",
                ));
            }
            basis[0] = (1.0, 0.0);
            for l in 1..=packet.order {
                work.reconstruction_terms += 2;
                let factor = omega_h / (l as f64);
                basis[l] = (-factor * basis[l - 1].1, factor * basis[l - 1].0);
                if !factor.is_finite() || !basis[l].0.is_finite() || !basis[l].1.is_finite() {
                    return Err(PacketError::OutwardRefusal("represented basis overflow"));
                }
            }

            let base = j * mode_stride;
            let z = packet.model.initial_amplitudes()[j];
            // Fhat_0 is not part of Y_j's constant coefficient.
            mode_coefficients[base] = z;
            for l in 1..=packet.order {
                work.reconstruction_terms += 1;
                mode_coefficients[base + l] = c_mul(basis[l], z);
                if !mode_coefficients[base + l].0.is_finite()
                    || !mode_coefficients[base + l].1.is_finite()
                {
                    return Err(PacketError::OutwardRefusal(
                        "represented linear coefficient overflow",
                    ));
                }
            }

            // Accumulate the beta convolution first. Apply physical h once
            // outside the sum; forcing coefficient zero first contributes to
            // the coefficient of tau^1.
            for l in 0..=packet.order {
                for (k, &force_k) in forcing.iter().enumerate() {
                    let exponent = l
                        .checked_add(k)
                        .and_then(|x| x.checked_add(1))
                        .ok_or(PacketError::SizeOverflow("represented convolution index"))?;
                    if exponent > maximum_degree {
                        return Err(PacketError::OutwardRefusal(
                            "represented convolution exceeds checked degree",
                        ));
                    }
                    work.volterra_terms += 1;
                    let term = c_scale(c_mul(basis[l], force_k), beta[l * beta_cols + k]);
                    convolution[exponent] = c_add(convolution[exponent], term);
                    if !convolution[exponent].0.is_finite() || !convolution[exponent].1.is_finite()
                    {
                        return Err(PacketError::OutwardRefusal(
                            "represented convolution coefficient overflow",
                        ));
                    }
                }
            }
            for m in 1..=maximum_degree {
                work.reconstruction_terms += 2;
                let linear = if m <= packet.order {
                    mode_coefficients[base + m]
                } else {
                    (0.0, 0.0)
                };
                let forced = c_scale(convolution[m], packet.horizon);
                mode_coefficients[base + m] = c_add(linear, forced);
                if !mode_coefficients[base + m].0.is_finite()
                    || !mode_coefficients[base + m].1.is_finite()
                {
                    return Err(PacketError::OutwardRefusal(
                        "represented mode coefficient overflow",
                    ));
                }
            }
        }

        let mut mean_coefficients = counted_capacity::<PacketComplexInterval>(
            mode_stride,
            "represented mean coefficients",
            work,
        )?;
        mean_coefficients.resize(mode_stride, IComplex::point((0.0, 0.0))?.into());
        for k in 0..mode_stride {
            let mut mean = IComplex::point((0.0, 0.0))?;
            for j in 0..n {
                work.certificate_items += 1;
                let weight = Interval::point(packet.model.weights()[j])
                    .map_err(|_| PacketError::OutwardRefusal("represented mean weight"))?;
                let mode = IComplex::point(mode_coefficients[j * mode_stride + k])?;
                mean =
                    interval_complex_add(mean, interval_complex_scale(mode, weight, work)?, work)?;
            }
            mean_coefficients[k] = mean.into();
        }

        let mut mean_i =
            counted_capacity::<IComplex>(mode_stride, "represented mean workspace", work)?;
        mean_i.extend(mean_coefficients.iter().copied().map(IComplex::from));
        let mean_conjugate = conjugate_coefficients(&mean_i, work)?;
        let mean_square = interval_polynomial_product(&mean_i, &mean_conjugate, work)?;
        let mean_square_mean = interval_polynomial_product(&mean_square, &mean_i, work)?;
        let nonlinear =
            rotate_and_scale_i_chi(&mean_square_mean, packet.model.chi(), residual_stride, work)?;

        let mut residual_coefficients = counted_capacity::<PacketComplexInterval>(
            residual_items,
            "represented residual coefficients",
            work,
        )?;
        residual_coefficients.resize(residual_items, IComplex::point((0.0, 0.0))?.into());
        // One outward reciprocal operation; charge before the fallible call.
        work.curve_setup_interval_ops += 1;
        let inv_h = Interval::point(1.0)
            .and_then(|one| one.div(Interval::point(packet.horizon)?))
            .map_err(|_| PacketError::OutwardRefusal("represented physical reciprocal"))?;
        for j in 0..n {
            // One outward frequency product per mode; charge before it can refuse.
            work.curve_setup_interval_ops += 1;
            let omega = Interval::point(packet.model.width())
                .and_then(|width| width.mul(Interval::point(packet.model.xi()[j])?))
                .map_err(|_| PacketError::OutwardRefusal("represented width-frequency"))?;
            let base_y = j * mode_stride;
            let base_r = j * residual_stride;
            for q in 0..residual_stride {
                let derivative = if q < maximum_degree {
                    work.certificate_items += 1;
                    let scale = Interval::point((q + 1) as f64)
                        .and_then(|integer| integer.mul(inv_h))
                        .map_err(|_| PacketError::OutwardRefusal("represented derivative scale"))?;
                    interval_complex_scale(
                        IComplex::point(mode_coefficients[base_y + q + 1])?,
                        scale,
                        work,
                    )?
                } else {
                    IComplex::point((0.0, 0.0))?
                };
                let linear = if q <= maximum_degree {
                    interval_i_omega_y(
                        IComplex::point(mode_coefficients[base_y + q])?,
                        omega,
                        work,
                    )?
                } else {
                    IComplex::point((0.0, 0.0))?
                };
                let rhs = interval_complex_add(linear, nonlinear[q], work)?;
                let residual = interval_complex_sub(derivative, rhs, work)?;
                residual_coefficients[base_r + q] = residual.into();
            }
        }

        let residual_bound = coefficient_sum_bound(
            &mean_coefficients,
            &residual_coefficients,
            n,
            residual_stride,
            packet.model.weights(),
            work,
        )?;
        let mut source_candidate_bits = counted_capacity::<(u64, u64)>(
            candidate.mean.len(),
            "represented source candidate identity",
            work,
        )?;
        for &(re, im) in &candidate.mean {
            work.identity_snapshot_items += 2;
            source_candidate_bits.push((re.to_bits(), im.to_bits()));
        }
        let source_identity = copy_identity(&packet.identity, work)?;
        Ok(Self {
            source_identity,
            source_candidate_bits,
            source_candidate_degree: candidate.degree,
            source_candidate_sweeps: candidate.sweeps,
            horizon: packet.horizon,
            maximum_degree,
            residual_stride,
            mode_coefficients,
            mean_coefficients,
            residual_coefficients,
            residual_bound,
        })
    }

    pub const fn maximum_degree(&self) -> usize {
        self.maximum_degree
    }
    pub const fn horizon(&self) -> f64 {
        self.horizon
    }
    pub fn mode_count(&self) -> usize {
        self.source_identity.model.num_modes()
    }

    pub fn mode_coefficients(&self, mode: usize) -> Option<&[(f64, f64)]> {
        if mode >= self.mode_count() {
            return None;
        }
        let stride = self.maximum_degree + 1;
        Some(&self.mode_coefficients[mode * stride..(mode + 1) * stride])
    }

    pub fn mean_coefficients(&self) -> &[PacketComplexInterval] {
        &self.mean_coefficients
    }
    pub fn residual_stride(&self) -> usize {
        self.residual_stride
    }

    pub const fn residual_bound(&self) -> ContinuousPacketResidualBound {
        self.residual_bound
    }

    pub fn residual_coefficients(&self, mode: usize) -> Option<&[PacketComplexInterval]> {
        if mode >= self.mode_count() {
            return None;
        }
        Some(
            &self.residual_coefficients
                [mode * self.residual_stride..(mode + 1) * self.residual_stride],
        )
    }

    /// Bind this curve to the exact source packet and candidate payload.
    pub fn validate_source(
        &self,
        candidate: &PacketCandidate,
        packet: &CompiledPacket,
        work: &mut PacketWorkCounters,
    ) -> Result<(), PacketError> {
        packet.validate_identity(work)?;
        work.identity_comparison_items += packet.identity.scalar_items();
        let model_payload_items = 4 * packet.model.num_modes() as u64 + 5;
        work.curve_model_revalidation_items += model_payload_items;
        let source_matches_packet = self.source_identity.matches(packet);
        work.curve_model_revalidation_items += model_payload_items;
        let source_matches_descriptor = self.source_identity.matches_identity(&packet.identity);
        work.curve_model_revalidation_items += model_payload_items;
        let candidate_matches_source = candidate.identity.matches_identity(&self.source_identity);
        if !source_matches_packet
            || !source_matches_descriptor
            || !candidate_matches_source
            || candidate.degree != self.source_candidate_degree
            || candidate.sweeps != self.source_candidate_sweeps
            || candidate.mean.len() != self.source_candidate_bits.len()
        {
            return Err(PacketError::CandidatePacketMismatch);
        }
        work.identity_comparison_items += candidate.mean.len() as u64 * 2;
        if candidate
            .mean
            .iter()
            .zip(&self.source_candidate_bits)
            .any(|(&(re, im), &(er, ei))| re.to_bits() != er || im.to_bits() != ei)
        {
            return Err(PacketError::CandidatePacketMismatch);
        }
        Ok(())
    }

    /// Evaluate frozen binary64 mode polynomials into caller storage. This
    /// operation performs no allocation.
    pub fn evaluate_modes_at_into(
        &self,
        time: f64,
        output: &mut [(f64, f64)],
        work: &mut PacketWorkCounters,
    ) -> Result<(), PacketError> {
        self.validate_time(time)?;
        if output.len() != self.mode_count() {
            return Err(PacketError::OutwardRefusal(
                "represented mode output shape mismatch",
            ));
        }
        work.curve_time_normalization_ops += 1;
        let tau = time / self.horizon;
        if !tau.is_finite() {
            return Err(PacketError::OutwardRefusal(
                "represented time normalization",
            ));
        }
        let stride = self.maximum_degree + 1;
        for (mode, result) in output.iter_mut().enumerate() {
            let base = mode * stride;
            let mut value = (0.0, 0.0);
            for q in (0..stride).rev() {
                work.output_horner_terms += 1;
                value = c_add(c_scale(value, tau), self.mode_coefficients[base + q]);
                if !value.0.is_finite() || !value.1.is_finite() {
                    return Err(PacketError::OutwardRefusal(
                        "represented mode evaluation overflow",
                    ));
                }
            }
            *result = value;
            work.output_value_items += 2;
        }
        Ok(())
    }

    /// Outwardly evaluate every frozen mode polynomial at physical time.
    pub fn enclose_modes_at_into(
        &self,
        time: f64,
        output: &mut [PacketComplexInterval],
        work: &mut PacketWorkCounters,
    ) -> Result<(), PacketError> {
        self.validate_time(time)?;
        if output.len() != self.mode_count() {
            return Err(PacketError::OutwardRefusal(
                "represented interval output shape mismatch",
            ));
        }
        work.curve_time_normalization_ops += 1;
        let tau = Interval::point(time)
            .and_then(|t| t.div(Interval::point(self.horizon)?))
            .map_err(|_| PacketError::OutwardRefusal("represented interval time normalization"))?;
        let stride = self.maximum_degree + 1;
        for (mode, result) in output.iter_mut().enumerate() {
            let base = mode * stride;
            let mut value = IComplex::point((0.0, 0.0))?;
            for q in (0..stride).rev() {
                work.certificate_items += 1;
                let scaled = interval_complex_scale(value, tau, work)?;
                value = interval_complex_add(
                    scaled,
                    IComplex::point(self.mode_coefficients[base + q])?,
                    work,
                )?;
            }
            *result = value.into();
        }
        Ok(())
    }

    /// Outwardly evaluate the exact weighted mean polynomial of the frozen
    /// mode coefficients; the candidate mean is not substituted.
    pub fn enclose_mean_at(
        &self,
        time: f64,
        work: &mut PacketWorkCounters,
    ) -> Result<PacketComplexInterval, PacketError> {
        self.validate_time(time)?;
        work.curve_time_normalization_ops += 1;
        let tau = Interval::point(time)
            .and_then(|t| t.div(Interval::point(self.horizon)?))
            .map_err(|_| PacketError::OutwardRefusal("represented mean time normalization"))?;
        let mut value = IComplex::point((0.0, 0.0))?;
        for coefficient in self.mean_coefficients.iter().rev() {
            work.certificate_items += 1;
            let scaled = interval_complex_scale(value, tau, work)?;
            value = interval_complex_add(scaled, (*coefficient).into(), work)?;
        }
        Ok(value.into())
    }

    fn validate_time(&self, time: f64) -> Result<(), PacketError> {
        if !time.is_finite() || time < 0.0 || time > self.horizon {
            return Err(PacketError::OutwardRefusal(
                "represented physical time outside curve horizon",
            ));
        }
        Ok(())
    }
}

fn checked_maximum_degree(order: usize, candidate_degree: usize) -> Result<usize, PacketError> {
    let degree = candidate_degree
        .checked_mul(3)
        .and_then(|triple| order.checked_add(triple))
        .and_then(|sum| sum.checked_add(1))
        .ok_or(PacketError::SizeOverflow("represented maximum degree"))?;
    let degree_u64 = u64::try_from(degree).map_err(|_| {
        PacketError::OutwardRefusal(
            "represented maximum degree exceeds exact binary64 integer range",
        )
    })?;
    if degree_u64 > (1_u64 << 53) {
        return Err(PacketError::OutwardRefusal(
            "represented maximum degree exceeds exact binary64 integer range",
        ));
    }
    Ok(degree)
}

#[cfg(test)]
mod degree_tests {
    use super::checked_maximum_degree;
    use crate::packet_window::PacketError;

    #[test]
    #[cfg(target_pointer_width = "64")]
    fn maximum_degree_guard_checks_binary64_integer_domain_without_allocation() {
        let exact_limit = (1_u64 << 53) as usize;
        assert_eq!(checked_maximum_degree(exact_limit - 1, 0), Ok(exact_limit));
        assert!(matches!(
            checked_maximum_degree(exact_limit, 0),
            Err(PacketError::OutwardRefusal(
                "represented maximum degree exceeds exact binary64 integer range"
            ))
        ));
        assert!(matches!(
            checked_maximum_degree(usize::MAX, 1),
            Err(PacketError::SizeOverflow("represented maximum degree"))
        ));
    }
}

fn rounded_candidate_force(
    candidate: &[(f64, f64)],
    chi: f64,
    work: &mut PacketWorkCounters,
) -> Result<Vec<(f64, f64)>, PacketError> {
    let degree = candidate
        .len()
        .checked_sub(1)
        .ok_or(PacketError::OutwardRefusal("empty represented candidate"))?;
    let square_len = degree
        .checked_mul(2)
        .and_then(|x| x.checked_add(1))
        .ok_or(PacketError::SizeOverflow("represented force square"))?;
    let cube_len = degree
        .checked_mul(3)
        .and_then(|x| x.checked_add(1))
        .ok_or(PacketError::SizeOverflow("represented force cube"))?;
    let mut conjugate =
        counted_capacity::<(f64, f64)>(candidate.len(), "represented candidate conjugate", work)?;
    for &(re, im) in candidate {
        work.reconstruction_terms += 1;
        conjugate.push((re, -im));
    }
    let square = rounded_product(candidate, &conjugate, square_len, work)?;
    let cube = rounded_product(&square, candidate, cube_len, work)?;
    let mut forcing = counted_capacity::<(f64, f64)>(cube_len, "represented forcing", work)?;
    for &(re, im) in &cube {
        work.reconstruction_terms += 2;
        let coefficient = (-chi * im, chi * re);
        if !coefficient.0.is_finite() || !coefficient.1.is_finite() {
            return Err(PacketError::OutwardRefusal("represented forcing overflow"));
        }
        forcing.push(coefficient);
    }
    Ok(forcing)
}

fn rounded_product(
    left: &[(f64, f64)],
    right: &[(f64, f64)],
    output_len: usize,
    work: &mut PacketWorkCounters,
) -> Result<Vec<(f64, f64)>, PacketError> {
    let mut output =
        counted_capacity::<(f64, f64)>(output_len, "represented polynomial product", work)?;
    output.resize(output_len, (0.0, 0.0));
    for (j, &a) in left.iter().enumerate() {
        for (k, &b) in right.iter().enumerate() {
            let index = j
                .checked_add(k)
                .ok_or(PacketError::SizeOverflow("represented product index"))?;
            if index >= output_len {
                return Err(PacketError::OutwardRefusal(
                    "represented product exceeds checked size",
                ));
            }
            work.poly_multiply_terms += 1;
            let product = c_mul(a, b);
            output[index] = c_add(output[index], product);
            if !output[index].0.is_finite() || !output[index].1.is_finite() {
                return Err(PacketError::OutwardRefusal(
                    "represented polynomial product overflow",
                ));
            }
        }
    }
    Ok(output)
}

fn interval_complex_add(
    a: IComplex,
    b: IComplex,
    work: &mut PacketWorkCounters,
) -> Result<IComplex, PacketError> {
    work.certificate_items += 1;
    Ok(IComplex {
        re: a
            .re
            .add(b.re)
            .map_err(|_| PacketError::OutwardRefusal("represented interval complex sum"))?,
        im: a
            .im
            .add(b.im)
            .map_err(|_| PacketError::OutwardRefusal("represented interval complex sum"))?,
    })
}

fn interval_complex_sub(
    a: IComplex,
    b: IComplex,
    work: &mut PacketWorkCounters,
) -> Result<IComplex, PacketError> {
    work.certificate_items += 1;
    Ok(IComplex {
        re: a
            .re
            .sub(b.re)
            .map_err(|_| PacketError::OutwardRefusal("represented interval complex difference"))?,
        im: a
            .im
            .sub(b.im)
            .map_err(|_| PacketError::OutwardRefusal("represented interval complex difference"))?,
    })
}

fn interval_complex_mul(
    a: IComplex,
    b: IComplex,
    work: &mut PacketWorkCounters,
) -> Result<IComplex, PacketError> {
    work.certificate_items += 1;
    a.mul(b)
}

fn interval_complex_scale(
    a: IComplex,
    scale: Interval,
    work: &mut PacketWorkCounters,
) -> Result<IComplex, PacketError> {
    work.certificate_items += 1;
    a.scale(scale)
}

fn interval_i_omega_y(
    y: IComplex,
    omega: Interval,
    work: &mut PacketWorkCounters,
) -> Result<IComplex, PacketError> {
    let scaled = interval_complex_scale(y, omega, work)?;
    Ok(IComplex {
        re: Interval::new(-scaled.im.hi, -scaled.im.lo)
            .map_err(|_| PacketError::OutwardRefusal("represented imaginary rotation"))?,
        im: scaled.re,
    })
}

fn conjugate_coefficients(
    polynomial: &[IComplex],
    work: &mut PacketWorkCounters,
) -> Result<Vec<IComplex>, PacketError> {
    let mut output =
        counted_capacity::<IComplex>(polynomial.len(), "represented mean conjugate", work)?;
    for coefficient in polynomial {
        work.certificate_items += 1;
        output.push(IComplex {
            re: coefficient.re,
            im: Interval::new(-coefficient.im.hi, -coefficient.im.lo)
                .map_err(|_| PacketError::OutwardRefusal("represented mean conjugate"))?,
        });
    }
    Ok(output)
}

fn interval_polynomial_product(
    left: &[IComplex],
    right: &[IComplex],
    work: &mut PacketWorkCounters,
) -> Result<Vec<IComplex>, PacketError> {
    let output_len = left
        .len()
        .checked_add(right.len())
        .and_then(|x| x.checked_sub(1))
        .ok_or(PacketError::SizeOverflow("represented interval product"))?;
    let mut output =
        counted_capacity::<IComplex>(output_len, "represented interval product", work)?;
    output.resize(output_len, IComplex::point((0.0, 0.0))?);
    for (j, &a) in left.iter().enumerate() {
        for (k, &b) in right.iter().enumerate() {
            let index = j.checked_add(k).ok_or(PacketError::SizeOverflow(
                "represented interval product index",
            ))?;
            work.certificate_items += 1;
            let term = interval_complex_mul(a, b, work)?;
            output[index] = interval_complex_add(output[index], term, work)?;
        }
    }
    Ok(output)
}

fn rotate_and_scale_i_chi(
    polynomial: &[IComplex],
    chi: f64,
    output_len: usize,
    work: &mut PacketWorkCounters,
) -> Result<Vec<IComplex>, PacketError> {
    if polynomial.len() > output_len {
        return Err(PacketError::OutwardRefusal(
            "represented nonlinear residual exceeds checked stride",
        ));
    }
    let mut output =
        counted_capacity::<IComplex>(output_len, "represented nonlinear residual", work)?;
    output.resize(output_len, IComplex::point((0.0, 0.0))?);
    let scale = Interval::point(chi)
        .map_err(|_| PacketError::OutwardRefusal("represented nonlinear coupling"))?;
    for (index, &coefficient) in polynomial.iter().enumerate() {
        let scaled = interval_complex_scale(coefficient, scale, work)?;
        work.certificate_items += 1;
        output[index] = IComplex {
            re: Interval::new(-scaled.im.hi, -scaled.im.lo)
                .map_err(|_| PacketError::OutwardRefusal("represented nonlinear rotation"))?,
            im: scaled.re,
        };
    }
    Ok(output)
}

fn counted_capacity<T>(
    len: usize,
    label: &'static str,
    work: &mut PacketWorkCounters,
) -> Result<Vec<T>, PacketError> {
    work.curve_setup_allocation_requests += 1;
    let items = u64::try_from(len).map_err(|_| PacketError::SizeOverflow(label))?;
    work.curve_setup_reserved_items += items;
    checked_capacity(len, label)
}

fn copied_slice<T: Copy>(
    source: &[T],
    label: &'static str,
    work: &mut PacketWorkCounters,
) -> Result<Vec<T>, PacketError> {
    let mut copy = counted_capacity::<T>(source.len(), label, work)?;
    work.identity_snapshot_items +=
        u64::try_from(source.len()).map_err(|_| PacketError::SizeOverflow(label))?;
    copy.extend_from_slice(source);
    Ok(copy)
}

fn copy_identity(
    source: &PacketIdentity,
    work: &mut PacketWorkCounters,
) -> Result<PacketIdentity, PacketError> {
    let source_model = &source.model;
    let xi = copied_slice(source_model.xi(), "represented identity xi", work)?;
    let weights = copied_slice(source_model.weights(), "represented identity weights", work)?;
    let initial = copied_slice(
        source_model.initial_amplitudes(),
        "represented identity initial state",
        work,
    )?;
    work.identity_snapshot_items += 5;
    let modes = u64::try_from(source_model.num_modes())
        .map_err(|_| PacketError::SizeOverflow("represented model constructor accounting"))?;
    let constructor_payload = modes
        .checked_mul(4)
        .and_then(|items| items.checked_add(4))
        .ok_or(PacketError::SizeOverflow(
            "represented model constructor accounting",
        ))?;
    let constructor_arithmetic = modes
        .checked_mul(6)
        .and_then(|ops| ops.checked_add(2))
        .ok_or(PacketError::SizeOverflow(
            "represented model constructor accounting",
        ))?;
    // These account for the constructor's actual payload and arithmetic before
    // its validation can refuse the copied source model.
    work.curve_model_constructor_payload_items += constructor_payload;
    work.curve_model_constructor_arithmetic_ops += constructor_arithmetic;
    let model = CollectiveModel::new(
        xi,
        weights,
        initial,
        source_model.width(),
        source_model.chi(),
        source_model.carrier(),
        source_model.kappa(),
    )
    .map_err(|_| PacketError::OutwardRefusal("represented model identity copy"))?;

    let mu = copied_slice(&source.mu, "represented identity moments", work)?;
    let nu = copied_slice(&source.nu, "represented identity candidate", work)?;
    let free = copied_slice(&source.free, "represented identity free kernel", work)?;
    let kernel = copied_slice(&source.kernel, "represented identity kernel", work)?;
    Ok(PacketIdentity {
        model,
        horizon: source.horizon,
        order: source.order,
        mu,
        nu,
        free,
        kernel,
    })
}

fn complex_magnitude_upper(
    value: PacketComplexInterval,
    work: &mut PacketWorkCounters,
) -> Result<f64, PacketError> {
    let re = value.re.mag();
    let im = value.im.mag();
    work.certificate_items += 1;
    let re2 = mul_up(re, re)
        .map_err(|_| PacketError::OutwardRefusal("represented coefficient magnitude"))?;
    work.certificate_items += 1;
    let im2 = mul_up(im, im)
        .map_err(|_| PacketError::OutwardRefusal("represented coefficient magnitude"))?;
    work.certificate_items += 1;
    let square = add_up(re2, im2)
        .map_err(|_| PacketError::OutwardRefusal("represented coefficient magnitude"))?;
    work.certificate_items += 1;
    sqrt_up(square).map_err(|_| PacketError::OutwardRefusal("represented coefficient magnitude"))
}

fn coefficient_sum_bound(
    mean: &[PacketComplexInterval],
    residual: &[PacketComplexInterval],
    modes: usize,
    residual_stride: usize,
    weights: &[f64],
    work: &mut PacketWorkCounters,
) -> Result<ContinuousPacketResidualBound, PacketError> {
    let expected_residual = modes
        .checked_mul(residual_stride)
        .ok_or(PacketError::SizeOverflow(
            "represented residual bound shape",
        ))?;
    if weights.len() != modes || residual.len() != expected_residual {
        return Err(PacketError::OutwardRefusal(
            "represented residual bound shape mismatch",
        ));
    }

    let mut mean_sup = 0.0;
    for &coefficient in mean {
        let magnitude = complex_magnitude_upper(coefficient, work)?;
        work.certificate_items += 1;
        mean_sup = add_up(mean_sup, magnitude)
            .map_err(|_| PacketError::OutwardRefusal("represented mean coefficient sum"))?;
    }

    let mut weighted_square_sup = 0.0;
    for (mode, &weight) in weights.iter().enumerate() {
        let mut mode_sup = 0.0;
        for &coefficient in &residual[mode * residual_stride..(mode + 1) * residual_stride] {
            let magnitude = complex_magnitude_upper(coefficient, work)?;
            work.certificate_items += 1;
            mode_sup = add_up(mode_sup, magnitude)
                .map_err(|_| PacketError::OutwardRefusal("represented residual coefficient sum"))?;
        }
        work.certificate_items += 1;
        let mode_square = mul_up(mode_sup, mode_sup)
            .map_err(|_| PacketError::OutwardRefusal("represented weighted residual norm"))?;
        work.certificate_items += 1;
        let weighted = mul_up(weight, mode_square)
            .map_err(|_| PacketError::OutwardRefusal("represented weighted residual norm"))?;
        work.certificate_items += 1;
        weighted_square_sup = add_up(weighted_square_sup, weighted)
            .map_err(|_| PacketError::OutwardRefusal("represented weighted residual norm"))?;
    }
    work.certificate_items += 1;
    let residual_sup = sqrt_up(weighted_square_sup)
        .map_err(|_| PacketError::OutwardRefusal("represented weighted residual norm"))?;

    Ok(ContinuousPacketResidualBound {
        weighted_residual_sup: Interval::new(0.0, residual_sup)
            .map_err(|_| PacketError::OutwardRefusal("represented weighted residual bound"))?,
        mean_magnitude_sup: Interval::new(0.0, mean_sup)
            .map_err(|_| PacketError::OutwardRefusal("represented mean magnitude bound"))?,
    })
}

//! Local T1 error transport for the exact curve frozen in `RepresentedPacketCurve`.
//! This object owns its sole curve; no candidate or external model may be rebound.

use rodas5p_core::directed::{Interval, add_up, div_up, exp_interval, mul_up, sqrt_down, sqrt_up};

use super::{PacketComplexInterval, RepresentedPacketCurve};
use crate::packet_window::{PacketError, PacketWorkCounters};

/// An owner of one frozen represented curve and its T1 output construction.
pub struct PacketCurveOutput {
    curve: RepresentedPacketCurve,
}

/// Owns one represented curve and a copied, immutable initial mode tube.
/// A query can only use the uncertainty supplied at construction.
///
/// ```compile_fail
/// use rodas5p_integrators::packet_window::PacketFrozenOutput;
/// fn alter(owner: &mut PacketFrozenOutput) { owner.initial_radii[0] = 0.0; }
/// ```
pub struct PacketFrozenOutput {
    output: PacketCurveOutput,
    initial_radii: Vec<f64>,
}

/// Immutable enclosure returned only from a frozen local packet owner.
/// This certifies inclusion at the requested time; it does not assert that
/// any requested application tolerance has been met.
///
/// ```compile_fail
/// use rodas5p_integrators::packet_window::PacketCertifiedView;
/// fn alter(view: &mut PacketCertifiedView<'_>) { view.inner = panic!(); }
/// ```
pub struct PacketCertifiedView<'a> {
    inner: PacketCurveOutputView<'a>,
}

impl PacketCertifiedView<'_> {
    pub fn time(&self) -> f64 {
        self.inner.time()
    }
    pub fn modes(&self) -> &[(f64, f64)] {
        self.inner.modes()
    }
    pub fn mode_radii(&self) -> &[f64] {
        self.inner.mode_radii()
    }
    pub fn mean(&self) -> (f64, f64) {
        self.inner.mean()
    }
    pub fn mean_radius(&self) -> f64 {
        self.inner.mean_radius()
    }
    pub fn weighted_radius(&self) -> f64 {
        self.inner.weighted_radius()
    }
}

impl PacketFrozenOutput {
    /// Copy the caller's uncertainty into the owner. The represented curve
    /// already owns its source model, coefficients, horizon, and residual.
    pub fn new(
        curve: RepresentedPacketCurve,
        initial_radii: &[f64],
        work: &mut PacketWorkCounters,
    ) -> Result<Self, PacketError> {
        let n = curve.mode_count();
        if initial_radii.len() != n {
            return Err(PacketError::OutwardRefusal(
                "frozen output initial radius shape mismatch",
            ));
        }
        if initial_radii.iter().any(|&x| !x.is_finite() || x < 0.0) {
            return Err(PacketError::OutwardRefusal("frozen output initial radius"));
        }
        if n > isize::MAX as usize / std::mem::size_of::<f64>() {
            return Err(PacketError::SizeOverflow("frozen output initial radii"));
        }
        work.curve_frozen_allocation_requests += 1;
        let mut frozen = Vec::new();
        frozen
            .try_reserve_exact(n)
            .map_err(|_| PacketError::SizeOverflow("frozen output initial radii"))?;
        for &radius in initial_radii {
            work.curve_frozen_radius_items += 1;
            frozen.push(radius);
        }
        Ok(Self {
            output: PacketCurveOutput::new(curve),
            initial_radii: frozen,
        })
    }

    pub fn workspace(
        &self,
        work: &mut PacketWorkCounters,
    ) -> Result<PacketCurveOutputWorkspace, PacketError> {
        self.output.workspace(work)
    }

    /// Evaluate the frozen curve and initial tube at one physical time.
    pub fn enclose_at<'a>(
        &'a self,
        time: f64,
        workspace: &'a mut PacketCurveOutputWorkspace,
        work: &mut PacketWorkCounters,
    ) -> Result<PacketCertifiedView<'a>, PacketError> {
        work.curve_frozen_query_attempts += 1;
        let result = self
            .output
            .enclose_at(time, &self.initial_radii, workspace, work);
        if result.is_err() {
            work.curve_frozen_query_refusals += 1;
        }
        result.map(|inner| PacketCertifiedView { inner })
    }
}

/// Caller-owned storage. Allocate once before evaluating requested times.
pub struct PacketCurveOutputWorkspace {
    centers: Vec<(f64, f64)>,
    boxes: Vec<PacketComplexInterval>,
    radii: Vec<f64>,
    mean_center: (f64, f64),
    mean_radius: f64,
    weighted_radius: f64,
    time: f64,
}

/// Borrowed output, valid only while its owner and completed workspace live.
/// Its fields are private; callers receive immutable borrowed slices.
///
/// ```compile_fail
/// use rodas5p_integrators::packet_window::PacketCurveOutputView;
/// fn alter(view: &mut PacketCurveOutputView<'_>) { view.mean_radius = 0.0; }
/// ```
/// ```compile_fail
/// use rodas5p_integrators::packet_window::PacketCurveOutputView;
/// fn replace(view: &mut PacketCurveOutputView<'_>) { view.modes = &[]; }
/// ```
pub struct PacketCurveOutputView<'a> {
    time: f64,
    modes: &'a [(f64, f64)],
    mode_radii: &'a [f64],
    mean: (f64, f64),
    mean_radius: f64,
    weighted_radius: f64,
    _curve: &'a PacketCurveOutput,
}

impl PacketCurveOutputView<'_> {
    pub fn time(&self) -> f64 {
        self.time
    }
    pub fn modes(&self) -> &[(f64, f64)] {
        self.modes
    }
    pub fn mode_radii(&self) -> &[f64] {
        self.mode_radii
    }
    pub fn mean(&self) -> (f64, f64) {
        self.mean
    }
    pub fn mean_radius(&self) -> f64 {
        self.mean_radius
    }
    pub fn weighted_radius(&self) -> f64 {
        self.weighted_radius
    }
}

impl PacketCurveOutput {
    pub fn new(curve: RepresentedPacketCurve) -> Self {
        Self { curve }
    }

    pub fn workspace(
        &self,
        work: &mut PacketWorkCounters,
    ) -> Result<PacketCurveOutputWorkspace, PacketError> {
        let n = self.curve.mode_count();
        Ok(PacketCurveOutputWorkspace {
            centers: reserve(n, (0.0, 0.0), work)?,
            boxes: reserve(
                n,
                PacketComplexInterval {
                    re: Interval::point(0.0)
                        .map_err(|_| PacketError::OutwardRefusal("represented output workspace"))?,
                    im: Interval::point(0.0)
                        .map_err(|_| PacketError::OutwardRefusal("represented output workspace"))?,
                },
                work,
            )?,
            radii: reserve(n, 0.0, work)?,
            mean_center: (0.0, 0.0),
            mean_radius: 0.0,
            weighted_radius: 0.0,
            time: 0.0,
        })
    }

    /// Enclose the true kappa=0 flow at an exact requested binary64 physical
    /// time. `initial_radii[j]` is a modulus radius around the curve's frozen
    /// initial amplitude. Every failure is a typed refusal and charges work.
    pub fn enclose_at<'a>(
        &'a self,
        time: f64,
        initial_radii: &[f64],
        workspace: &'a mut PacketCurveOutputWorkspace,
        work: &mut PacketWorkCounters,
    ) -> Result<PacketCurveOutputView<'a>, PacketError> {
        let n = self.curve.mode_count();
        if initial_radii.len() != n
            || workspace.centers.len() != n
            || workspace.boxes.len() != n
            || workspace.radii.len() != n
        {
            return Err(PacketError::OutwardRefusal(
                "represented output shape mismatch",
            ));
        }
        if !time.is_finite() || time < 0.0 || time > self.curve.horizon() {
            return Err(PacketError::OutwardRefusal(
                "represented output physical time",
            ));
        }
        let model = &self.curve.source_identity.model;
        let weights = model.weights();
        let initial = model.initial_amplitudes();
        let mut s = 0.0;
        let mut energy = 0.0;
        let mut initial_error_square = 0.0;
        for j in 0..n {
            let w = weights[j];
            let eta = initial_radii[j];
            if !w.is_finite() || w <= 0.0 || !eta.is_finite() || eta < 0.0 {
                return Err(PacketError::OutwardRefusal(
                    "represented output initial tube",
                ));
            }
            s = add(s, w, work, "represented output weight sum")?;
            let z_abs = magnitude(initial[j].0, initial[j].1, work)?;
            let amplitude = add(z_abs, eta, work, "represented output initial amplitude")?;
            let amplitude_square = mul(amplitude, amplitude, work, "represented output energy")?;
            let weighted_energy = mul(w, amplitude_square, work, "represented output energy")?;
            energy = add(energy, weighted_energy, work, "represented output energy")?;
            let eta_square = mul(eta, eta, work, "represented output initial error")?;
            let weighted_error = mul(w, eta_square, work, "represented output initial error")?;
            initial_error_square = add(
                initial_error_square,
                weighted_error,
                work,
                "represented output initial error",
            )?;
        }
        let e0 = sqrt_upper(
            initial_error_square,
            work,
            "represented output initial error",
        )?;
        let m_y = self.curve.residual_bound.mean_magnitude_sup.hi;
        let rho = self.curve.residual_bound.weighted_residual_sup.hi;
        let se = mul(s, energy, work, "represented output gain")?;
        let my2 = mul(m_y, m_y, work, "represented output gain")?;
        let schi = mul(s, model.chi().abs(), work, "represented output gain")?;
        let lambda = mul(schi, se.max(my2), work, "represented output gain")?;
        let exponent = mul(lambda, time, work, "represented output gain")?;
        work.curve_output_certificate_ops += 1; // one exp_interval kernel
        let gain = exp_interval(exponent)
            .map_err(|_| PacketError::OutwardRefusal("represented output exponential gain"))?
            .hi;
        let residual_increment = mul(time, rho, work, "represented output residual")?;
        let seeded_radius = add(e0, residual_increment, work, "represented output radius")?;
        let weighted_radius = mul(gain, seeded_radius, work, "represented output radius")?;

        // Evaluate the same stored curve in binary64 and exact-real interval
        // arithmetic. The resulting displacement encloses evaluation rounding.
        self.curve
            .evaluate_modes_at_into(time, &mut workspace.centers, work)?;
        self.curve
            .enclose_modes_at_into(time, &mut workspace.boxes, work)?;
        for j in 0..n {
            work.curve_output_certificate_ops += 1; // sqrt_down
            let denominator = sqrt_down(weights[j])
                .map_err(|_| PacketError::OutwardRefusal("represented output weight root"))?;
            if denominator <= 0.0 {
                return Err(PacketError::OutwardRefusal(
                    "represented output weight root vanished",
                ));
            }
            let flow = div(
                weighted_radius,
                denominator,
                work,
                "represented output mode radius",
            )?;
            let delta = displacement(workspace.centers[j], workspace.boxes[j], work)?;
            workspace.radii[j] = add(flow, delta, work, "represented output mode radius")?;
        }

        let mut mean = (0.0, 0.0);
        for (j, &(re, im)) in workspace.centers.iter().enumerate() {
            work.curve_output_certificate_ops += 1;
            let real_term = weights[j] * re;
            if !real_term.is_finite() {
                return Err(PacketError::OutwardRefusal(
                    "represented output mean center",
                ));
            }
            work.curve_output_certificate_ops += 1;
            mean.0 += real_term;
            if !mean.0.is_finite() {
                return Err(PacketError::OutwardRefusal(
                    "represented output mean center",
                ));
            }
            work.curve_output_certificate_ops += 1;
            let imaginary_term = weights[j] * im;
            if !imaginary_term.is_finite() {
                return Err(PacketError::OutwardRefusal(
                    "represented output mean center",
                ));
            }
            work.curve_output_certificate_ops += 1;
            mean.1 += imaginary_term;
            if !mean.0.is_finite() || !mean.1.is_finite() {
                return Err(PacketError::OutwardRefusal(
                    "represented output mean center",
                ));
            }
        }
        let mean_box = self.curve.enclose_mean_at(time, work)?;
        let mean_delta = displacement(mean, mean_box, work)?;
        let root_s = sqrt_upper(s, work, "represented output weight root")?;
        let mean_flow = mul(
            root_s,
            weighted_radius,
            work,
            "represented output mean radius",
        )?;
        let mean_radius = add(
            mean_flow,
            mean_delta,
            work,
            "represented output mean radius",
        )?;
        workspace.mean_center = mean;
        workspace.mean_radius = mean_radius;
        workspace.weighted_radius = weighted_radius;
        workspace.time = time;
        Ok(PacketCurveOutputView {
            time: workspace.time,
            modes: &workspace.centers,
            mode_radii: &workspace.radii,
            mean: workspace.mean_center,
            mean_radius: workspace.mean_radius,
            weighted_radius: workspace.weighted_radius,
            _curve: self,
        })
    }
}

fn reserve<T: Clone>(
    n: usize,
    value: T,
    work: &mut PacketWorkCounters,
) -> Result<Vec<T>, PacketError> {
    if n > isize::MAX as usize / std::mem::size_of::<T>().max(1) {
        return Err(PacketError::SizeOverflow("represented output workspace"));
    }
    work.curve_output_allocation_requests += 1;
    let mut values = Vec::new();
    values
        .try_reserve_exact(n)
        .map_err(|_| PacketError::SizeOverflow("represented output workspace"))?;
    values.resize(n, value);
    Ok(values)
}

// Each wrapper charges one attempted directed operation before a possible
// overflow/refusal. Constructor shape checks and finite-input validation are
// excluded; underlying curve evaluation retains its existing counters.
fn add(
    a: f64,
    b: f64,
    work: &mut PacketWorkCounters,
    reason: &'static str,
) -> Result<f64, PacketError> {
    work.curve_output_certificate_ops += 1;
    add_up(a, b).map_err(|_| PacketError::OutwardRefusal(reason))
}
fn mul(
    a: f64,
    b: f64,
    work: &mut PacketWorkCounters,
    reason: &'static str,
) -> Result<f64, PacketError> {
    work.curve_output_certificate_ops += 1;
    mul_up(a, b).map_err(|_| PacketError::OutwardRefusal(reason))
}
fn div(
    a: f64,
    b: f64,
    work: &mut PacketWorkCounters,
    reason: &'static str,
) -> Result<f64, PacketError> {
    work.curve_output_certificate_ops += 1;
    div_up(a, b).map_err(|_| PacketError::OutwardRefusal(reason))
}
fn sqrt_upper(
    a: f64,
    work: &mut PacketWorkCounters,
    reason: &'static str,
) -> Result<f64, PacketError> {
    work.curve_output_certificate_ops += 1;
    sqrt_up(a).map_err(|_| PacketError::OutwardRefusal(reason))
}

fn magnitude(re: f64, im: f64, work: &mut PacketWorkCounters) -> Result<f64, PacketError> {
    let re2 = mul(re, re, work, "represented output magnitude")?;
    let im2 = mul(im, im, work, "represented output magnitude")?;
    let square = add(re2, im2, work, "represented output magnitude")?;
    sqrt_upper(square, work, "represented output magnitude")
}

fn displacement(
    center: (f64, f64),
    box_value: PacketComplexInterval,
    work: &mut PacketWorkCounters,
) -> Result<f64, PacketError> {
    work.curve_output_certificate_ops += 1;
    let point_re = Interval::point(center.0)
        .map_err(|_| PacketError::OutwardRefusal("represented output center"))?;
    work.curve_output_certificate_ops += 1;
    let point_im = Interval::point(center.1)
        .map_err(|_| PacketError::OutwardRefusal("represented output center"))?;
    work.curve_output_certificate_ops += 1;
    let re = box_value
        .re
        .sub(point_re)
        .map_err(|_| PacketError::OutwardRefusal("represented output displacement"))?;
    work.curve_output_certificate_ops += 1; // Interval::mag
    let re = re.mag();
    work.curve_output_certificate_ops += 1;
    let im = box_value
        .im
        .sub(point_im)
        .map_err(|_| PacketError::OutwardRefusal("represented output displacement"))?;
    work.curve_output_certificate_ops += 1; // Interval::mag
    let im = im.mag();
    let re2 = mul(re, re, work, "represented output displacement")?;
    let im2 = mul(im, im, work, "represented output displacement")?;
    let square = add(re2, im2, work, "represented output displacement")?;
    sqrt_upper(square, work, "represented output displacement")
}

//! Work counters and resource tracking for the causal packet integrator (LP02).
//!
//! Tracks selected arithmetic terms and binary64 payload movement in the causal
//! packet compiler, Picard waveform generator, certificate evaluator, and mode
//! reconstructor. This is not a complete setup/runtime cost model.
//!
//! Note: Online Jacobian builds, JVPs, VJPs, Krylov iterations, and linear
//! solves are strictly zero by design.

use serde::{Deserialize, Serialize};

/// Work counters recording operations performed by the causal packet pipeline.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(default)]
pub struct PacketWorkCounters {
    /// Binary64 payload items copied into packet/candidate identity snapshots.
    pub identity_snapshot_items: u64,
    /// Binary64 payload items compared while validating identities; metadata
    /// length/order checks are not included in this count.
    pub identity_comparison_items: u64,
    /// Binary64 payload items copied while cloning the model into a packet.
    pub model_copy_items: u64,
    /// Stored weight/support scalar inputs reduced while constructing a packet
    /// model-bounds snapshot.
    pub model_bounds_snapshot_items: u64,
    /// Stored weight/support scalar inputs re-read while validating the
    /// model-bounds snapshot before certificate or output use.
    pub model_bounds_comparison_items: u64,
    /// Binary64 payload items copied while restricting a candidate for output.
    pub output_copy_items: u64,
    /// Binary64 scalar values written into returned reconstructed modes.
    pub output_value_items: u64,
    /// Scalar multiplications used to restrict the candidate polynomial.
    pub output_restriction_multiplies: u64,
    /// Scalar coefficient/mode items visited by certificate setup and bounds.
    pub certificate_items: u64,
    /// Directed spectral-power recurrence products in outward moment replay.
    /// A failed product remains charged as attempted work.
    pub outward_spectral_power_terms: u64,
    /// Interval coefficient-ratio and accumulation terms in an adaptive
    /// Bernstein transform. Zero when the cheap coefficient gate passes.
    pub bernstein_transform_terms: u64,
    /// Complex control-point averages in dyadic de Casteljau subdivision.
    pub bernstein_refinement_terms: u64,
    /// Scalar arithmetic terms used to build reconstruction polynomials.
    pub reconstruction_terms: u64,
    /// Number of scalar spectral/weighted moment accumulations.
    pub moment_terms: u64,
    /// Number of scalar complex product terms in polynomial multiplications.
    pub poly_multiply_terms: u64,
    /// Number of causal Volterra convolution terms evaluated.
    pub volterra_terms: u64,
    /// Number of nonlinear force evaluations F(p) = i * chi * |p|^2 * p.
    pub nonlinear_evaluations: u64,
    /// Number of Horner polynomial evaluation steps at output times.
    pub output_horner_terms: u64,
    /// Number of fallible setup-buffer reservation attempts for represented
    /// packet curves. Each attempt is charged before reservation.
    pub curve_setup_allocation_requests: u64,
    /// Number of coefficient/workspace items requested in represented-curve
    /// setup reservations, charged before the fallible reserve.
    pub curve_setup_reserved_items: u64,
    /// Fallible outward setup operations for reciprocal horizon and per-mode
    /// frequency products, charged before each attempted interval operation.
    pub curve_setup_interval_ops: u64,
    /// Center or interval divisions that normalize a requested physical time
    /// for represented-curve evaluation, charged before the division.
    pub curve_time_normalization_ops: u64,
    /// Model-payload scalar comparisons when revalidating the copied source
    /// model identity for represented-curve use.
    pub curve_model_revalidation_items: u64,
    /// Constructor payload scalar items passed to `CollectiveModel::new` while
    /// making the fallible represented-curve source identity copy.
    pub curve_model_constructor_payload_items: u64,
    /// Scalar arithmetic operations performed by `CollectiveModel::new` for
    /// the represented-curve source identity copy, charged before the call.
    pub curve_model_constructor_arithmetic_ops: u64,
    /// Attempted T1 output arithmetic: each directed scalar/Interval operation,
    /// each magnitude query, one validated exponential kernel, and each
    /// ordinary mean-center product/sum. Precharged before a fallible call;
    /// represented-curve evaluation uses its existing separate counters.
    /// Constructor shape checks and finite-input validation are excluded.
    pub curve_output_certificate_ops: u64,
    /// Fallible preallocation attempts for the represented-curve output workspace.
    pub curve_output_allocation_requests: u64,
    /// Frozen local-output constructor reservation attempts.
    pub curve_frozen_allocation_requests: u64,
    /// Initial uncertainty scalars copied into a frozen local-output owner.
    pub curve_frozen_radius_items: u64,
    /// Calls attempted on the frozen local-output owner, including refusals.
    pub curve_frozen_query_attempts: u64,
    /// Typed refusals returned by the frozen local-output owner.
    pub curve_frozen_query_refusals: u64,
}

impl PacketWorkCounters {
    /// Constructs a zeroed [`PacketWorkCounters`].
    pub const fn new() -> Self {
        Self {
            identity_snapshot_items: 0,
            identity_comparison_items: 0,
            model_copy_items: 0,
            model_bounds_snapshot_items: 0,
            model_bounds_comparison_items: 0,
            output_copy_items: 0,
            output_value_items: 0,
            output_restriction_multiplies: 0,
            certificate_items: 0,
            outward_spectral_power_terms: 0,
            bernstein_transform_terms: 0,
            bernstein_refinement_terms: 0,
            reconstruction_terms: 0,
            moment_terms: 0,
            poly_multiply_terms: 0,
            volterra_terms: 0,
            nonlinear_evaluations: 0,
            output_horner_terms: 0,
            curve_setup_allocation_requests: 0,
            curve_setup_reserved_items: 0,
            curve_setup_interval_ops: 0,
            curve_time_normalization_ops: 0,
